<?php $section=$section??'dashboard';$record=$record??[];$records=$records??[];$fields=$fields??[];$adminSections=$adminSections??['dashboard','content','sessions','plans','users','inquiries','subscribers','orders','settings','sources','audit']; ?>
<section class="container section-top admin-section"><?php ff_heading('admin','Manage content and demonstration activity.'); ?><nav class="subnav admin-nav" aria-label="<?=e(t('admin'))?>"><?php foreach($adminSections as $key=>$value): $name=is_numeric($key)?$value:$key;$label=is_numeric($key)?$value:$value; ?><a href="<?=e(url('admin',['section'=>$name]))?>" <?=$section===$name?'aria-current="page"':''?>><?=e(t($label))?></a><?php endforeach ?></nav>
<?php if($section==='dashboard'): ?><div class="stat-grid"><?php foreach($stats??[] as $key=>$value): ?><div class="stat-card"><span><?=e(t($key))?></span><strong><?=e(is_scalar($value)?$value:'—')?></strong></div><?php endforeach ?></div><div class="notice"><p><?=e(t('All orders, revenue, memberships and reservations shown here are demonstration records. Contact and business source status must remain accurate when editing content.'))?></p></div>
<?php else: ?><div class="section-heading"><h2><?=e(t($section))?></h2><?php if(in_array($section,['content','sessions','plans','sources','rooms'])): ?><a class="button small" href="<?=e(url('admin',['section'=>$section,'edit'=>'new']))?>"><?=e(t('create_new'))?> +</a><?php endif ?></div>
<?php if($record && in_array($section,['users','orders','bookings','inquiries','subscribers'],true)): ?>
<section class="panel admin-edit"><h3><?=e($record['subject']??$record['name']??$record['title']??$record['reference']??t('record_details'))?></h3><dl class="detail-facts"><?php foreach($record as $key=>$value): if(is_scalar($value)&&!in_array($key,['password_hash','token','unsubscribe_token','message','ip_hash','idempotency_key','user_agent'],true)): ?><div><dt><?=e(t($key))?></dt><dd><?=e(ff_admin_value($key,$value))?></dd></div><?php endif; endforeach ?></dl><?php if(!empty($record['message'])): ?><h3><?=e(t('message'))?></h3><p class="prose"><?=nl2br(e($record['message']))?></p><?php endif ?>
<?php $statusOptions=match($section){'users'=>['active','inactive'],'orders'=>($record['status']??'')==='pending'?['paid','failed','cancelled']:[],'bookings'=>($record['status']??'')==='confirmed'?['attended','no_show']:[],'inquiries'=>['new','read','resolved'],'subscribers'=>['unsubscribed'],default=>[]}; ?>
<?php if($statusOptions): ?><form method="post" class="form-stack" data-confirm="<?=e(t('Apply this status change to the demonstration record?'))?>"><?=csrf_field()?><input type="hidden" name="action" value="admin_status"><input type="hidden" name="entity" value="<?=e($section)?>"><input type="hidden" name="id" value="<?=e($record['id'])?>"><label><span><?=e(t('status'))?></span><select name="status"><?php foreach($statusOptions as $statusOption): ?><option value="<?=e($statusOption)?>" <?=($record['status']??(($record['active']??0)?'active':'inactive'))===$statusOption?'selected':''?>><?=e(t($statusOption))?></option><?php endforeach ?></select></label><?php if($section==='orders'): ?><p class="fine-print"><?=e(t('Marking a pending order paid activates its demo membership once. No real payment is involved.'))?></p><?php elseif($section==='bookings'): ?><p class="fine-print"><?=e(t('Attendance can only be recorded after the session ends.'))?></p><?php endif ?><button class="button" type="submit"><?=e(t('update_status'))?> <?=ff_icon('check')?></button></form><?php else: ?><p class="notice compact"><?=e(t('This record has no further valid status transitions.'))?></p><?php endif ?></section>
<?php endif ?><?php if($fields && (isset($_GET['edit'])||$record)): ?><form method="post" class="panel admin-edit form-stack" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="admin_save"><input type="hidden" name="entity" value="<?=e($section)?>"><input type="hidden" name="id" value="<?=e($record['id']??'')?>"><h3><?=e(t($record?'edit_record':'create_record'))?></h3><div class="form-grid"><?php foreach($fields as $name=>$field): if(is_string($field))$field=['label'=>$field,'type'=>'text']; $type=$field['type']??'text';$value=$_POST[$name]??$record[$name]??$field['default']??''; ?><label class="<?=$type==='textarea'?'span-two':''?>"><span><?=e(t($field['label']??$name))?></span><?php if($type==='textarea'): ?><textarea name="<?=e($name)?>" rows="<?=in_array($name,['body','description'])?8:3?>" <?=!empty($field['required'])?'required':''?>><?=e(is_scalar($value)?$value:json_encode($value,JSON_UNESCAPED_UNICODE))?></textarea><?php elseif($type==='select'): ?><select name="<?=e($name)?>" <?=!empty($field['required'])?'required':''?>><?php foreach($field['options']??[] as $option=>$label): ?><option value="<?=e($option)?>" <?=(string)$value===(string)$option?'selected':''?>><?=e(t($label))?></option><?php endforeach ?></select><?php elseif($type==='checkbox'): ?><input type="hidden" name="<?=e($name)?>" value="0"><input type="checkbox" name="<?=e($name)?>" value="1" <?=$value?'checked':''?>><?php else: ?><input type="<?=e($type)?>" name="<?=e($name)?>" <?=$type!=='file'?'value="'.e($value).'"':''?> <?=!empty($field['required'])?'required':''?> <?=isset($field['min'])?'min="'.e($field['min']).'"':''?> <?=isset($field['max'])?'max="'.e($field['max']).'"':''?> <?=$type==='file'?'accept="image/jpeg,image/png,image/webp"':''?>><?php endif ?><?php if(!empty($field['hint'])): ?><small><?=e(t($field['hint']))?></small><?php endif ?></label><?php endforeach ?></div><div class="button-row"><button class="button" type="submit"><?=e(t('save_changes'))?> <?=ff_icon('check')?></button><a href="<?=e(url('admin',['section'=>$section]))?>" class="text-link"><?=e(t('cancel'))?></a></div></form><?php endif ?>
<?php if($section==='content'): ?><form method="get" class="filter-bar"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="content"><label><span><?=e(t('content_type'))?></span><select name="kind"><option value=""><?=e(t('all_categories'))?></option><?php foreach(['service','facility','trainer','class_type','news','faq','gallery'] as $kind): ?><option value="<?=$kind?>" <?=($_GET['kind']??'')===$kind?'selected':''?>><?=e(t($kind))?></option><?php endforeach ?></select></label><button class="button small dark"><?=e(t('filter'))?></button></form><?php endif ?>
<?php if($records): $columns=$columns??array_values(array_filter(array_keys($records[0]),fn($key)=>!in_array($key,['password_hash','token','metadata','body','description','message','snapshot','settings','payload','alt','summary','email_token','idempotency_key','content','user_agent','ip_hash'])));$columns=array_slice($columns,0,8); ?><div class="table-wrap"><table><thead><tr><?php foreach($columns as $column): ?><th scope="col"><?=e(t($column))?></th><?php endforeach ?><th scope="col"><?=e(t('actions'))?></th></tr></thead><tbody><?php foreach($records as $row): ?><tr><?php foreach($columns as $column): ?><td><?=e(is_scalar($row[$column]??null)?mb_strimwidth(ff_admin_value($column,$row[$column]),0,130,'…'):'—')?></td><?php endforeach ?><td><div class="table-actions"><?php if(!in_array($section,['audit'])): ?><a class="text-link" href="<?=e(url('admin',['section'=>$section,'edit'=>$row['id']??$row['setting_key']??'']))?>"><?=e(t('edit'))?></a><?php endif ?><?php if(in_array($section,['content','sessions','plans'])): ?><form method="post" data-confirm="<?=e(t('Archive or cancel this record? Referenced history will be preserved.'))?>"><?=csrf_field()?><input type="hidden" name="action" value="<?=$section==='sessions'?'admin_status':'admin_archive'?>"><input type="hidden" name="confirm" value="1"><input type="hidden" name="status" value="cancelled"><input type="hidden" name="entity" value="<?=e($section)?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><button type="submit" class="link-button danger-text"><?=e(t($section==='sessions'?'cancel':'archive'))?></button></form><?php endif ?></div></td></tr><?php endforeach ?></tbody></table></div><?php else: ff_empty('No records found.','admin'); endif ?>
<?php if($section==='content'): ?><section class="panel upload-panel"><h3><?=e(t('upload_image'))?></h3><p><?=e(t('Upload your authorized JPEG, PNG or WebP image. After upload, use the returned path in the content image field and add descriptive alt text.'))?></p><form method="post" enctype="multipart/form-data" class="form-stack"><?=csrf_field()?><input type="hidden" name="action" value="upload"><label><span><?=e(t('image'))?></span><input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><button class="button secondary" type="submit"><?=e(t('upload'))?></button></form></section><?php endif ?>
<?php endif ?></section>
